/** Referências 2D. Não converte imagens em malhas 3D. */
const manifestUrl=new URL('./bustos.json',import.meta.url);
let manifestPromise;const images=new Map();let sequence=0;
export function loadBustCatalog(){if(!manifestPromise)manifestPromise=fetch(manifestUrl).then(r=>{if(!r.ok)throw new Error("Nao foi possivel carregar bustos.json. Use um servidor HTTP local.");return r.json();}).catch(error=>{manifestPromise=undefined;throw error;});return manifestPromise;}
function loadImage(url){if(!images.has(url))images.set(url,new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>{images.delete(url);reject(new Error('Imagem indisponível: '+url));};image.src=url;}));return images.get(url);}
export async function getBustReference(id){const data=await loadBustCatalog();const president=data.presidents.find(p=>p.id===id);if(!president)throw new Error('Presidente desconhecido: '+id);const atlas=data.atlases.find(a=>a.id===president.atlas);if(!atlas)throw new Error('Prancha desconhecida: '+president.atlas);const image=await loadImage(new URL(atlas.src,manifestUrl).href);const [x,y,w,h]=president.rect;const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Conceito visual de '+president.name+' — imagem gerada por IA');const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Canvas 2D indisponível.');ctx.drawImage(image,x,y,w,h,0,0,w,h);return {president,canvas};}
export async function showBustReference(container,id){const {president,canvas}=await getBustReference(id);container.replaceChildren(canvas);return president;}
/** Exibe uma referência em um painel plano dentro de uma cena A-Frame. */
export function registerBustReferenceComponent(AFRAME){if(AFRAME.components['busto-referencia'])return;AFRAME.registerComponent('busto-referencia',{schema:{presidente:{type:'string',default:'lula'},largura:{type:'number',default:1.2}},init(){this.request=0;},update(){const request=++this.request;getBustReference(this.data.presidente).then(({president,canvas})=>{if(request!==this.request)return;this.textureCanvas?.remove();canvas.id='busto-referencia-textura-'+(++sequence);canvas.hidden=true;document.body.append(canvas);this.textureCanvas=canvas;this.el.setAttribute('geometry',{primitive:'plane',width:this.data.largura,height:this.data.largura*canvas.height/canvas.width});this.el.setAttribute('material',{shader:'flat',side:'double',src:'#'+canvas.id});this.el.emit('busto-referencia-carregado',{president});}).catch(error=>{if(request===this.request)this.el.emit('busto-referencia-erro',{message:error.message});});},remove(){this.request++;this.textureCanvas?.remove();}});}
